package examples.safe_area;

import io.github._3xhaust.core.App;
import io.github._3xhaust.core.View;
import io.github._3xhaust.platform.javafx.JavaFXRenderer;
import javafx.application.Application;
import javafx.stage.Stage;

import static io.github._3xhaust.dsl.Layouts.*;
import static io.github._3xhaust.dsl.Widgets.*;

public class SafeAreaExample extends Application {

    @Override
    public void start(Stage primaryStage) {
        JavaFXRenderer renderer = new JavaFXRenderer(primaryStage);
        App app = new App(renderer);

        View ui = SafeArea(
            Column(
                Text("SafeArea 테스트"),
                Text("현재 플랫폼: " + getPlatformInfo()),
                Text("데스크톱에서는 패딩 없음"),
                Text("모바일에서는 Safe Area 적용"),
                Button("테스트 버튼", () -> System.out.println("버튼 클릭!"))
            ).gap(20).padding(20)
        );

        app.run("SafeArea 예제", 400, 600, ui);
    }

    private String getPlatformInfo() {
        String os = System.getProperty("os.name").toLowerCase();
        if (os.contains("windows")) return "Windows (데스크톱)";
        if (os.contains("mac")) return "macOS (데스크톱)";
        if (os.contains("linux")) return "Linux (데스크톱)";
        if (os.contains("android")) return "Android (모바일)";
        if (os.contains("ios")) return "iOS (모바일)";
        return "알 수 없는 플랫폼";
    }

    public static void main(String[] args) {
        launch(args);
    }
}

package io.github._3xhaust.annotations;

import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;

@Target(ElementType.TYPE)
@Retention(RetentionPolicy.RUNTIME)
public @interface WidgetFactory {
    String name();
    String[] aliases() default {};
}

package io.github._3xhaust.dsl;

import io.github._3xhaust.core.Insets;
import io.github._3xhaust.core.Renderer;
import io.github._3xhaust.core.View;
import io.github._3xhaust.utils.PlatformUtils;

/**
 * SafeArea provides a safe area for content, avoiding system UI elements like
 * status bars, navigation bars, and notches on mobile devices.
 */
public class SafeArea implements View {
    private final View child;
    private final boolean top;
    private final boolean left;
    private final boolean bottom;
    private final boolean right;

    /**
     * Creates a SafeArea that avoids all system UI elements.
     * 
     * @param child The child view to be wrapped in safe area
     */
    public SafeArea(View child) {
        this(child, true, true, true, true);
    }

    /**
     * Creates a SafeArea with selective safe area application.
     * 
     * @param child The child view to be wrapped in safe area
     * @param top Whether to apply safe area padding to the top
     * @param left Whether to apply safe area padding to the left
     * @param bottom Whether to apply safe area padding to the bottom
     * @param right Whether to apply safe area padding to the right
     */
    public SafeArea(View child, boolean top, boolean left, boolean bottom, boolean right) {
        this.child = child;
        this.top = top;
        this.left = left;
        this.bottom = bottom;
        this.right = right;
    }

    /**
     * Factory method for creating SafeArea that only applies to top.
     */
    public static SafeArea top(View child) {
        return new SafeArea(child, true, false, false, false);
    }

    /**
     * Factory method for creating SafeArea that only applies to bottom.
     */
    public static SafeArea bottom(View child) {
        return new SafeArea(child, false, false, true, false);
    }

    /**
     * Factory method for creating SafeArea that applies to top and bottom.
     */
    public static SafeArea vertical(View child) {
        return new SafeArea(child, true, false, true, false);
    }

    /**
     * Factory method for creating SafeArea that applies to left and right.
     */
    public static SafeArea horizontal(View child) {
        return new SafeArea(child, false, true, false, true);
    }

    /**
     * Gets the platform-specific safe area insets.
     * 
     * @return Insets representing the safe area for the current platform
     */
    private Insets getSafeAreaInsets() {
        if (PlatformUtils.isDesktop()) {
            // Desktop platforms typically don't need safe areas
            return new Insets(0, 0, 0, 0);
        }

        if (PlatformUtils.isIOS()) {
            // iOS safe areas for different device types
            return new Insets(
                top ? getIOSTopInset() : 0,
                left ? getIOSLeftInset() : 0,
                bottom ? getIOSBottomInset() : 0,
                right ? getIOSRightInset() : 0
            );
        }

        if (PlatformUtils.isAndroid()) {
            // Android safe areas
            return new Insets(
                top ? getAndroidTopInset() : 0,
                left ? getAndroidLeftInset() : 0,
                bottom ? getAndroidBottomInset() : 0,
                right ? getAndroidRightInset() : 0
            );
        }

        // Default fallback
        return new Insets(0, 0, 0, 0);
    }

    /**
     * Gets iOS-specific top inset (status bar + notch area).
     */
    private int getIOSTopInset() {
        // Standard status bar height + notch area for newer devices
        return 44;
    }

    /**
     * Gets iOS-specific left inset (for landscape orientation with notch).
     */
    private int getIOSLeftInset() {
        return 0; // Usually 0, but could be adjusted for landscape notch
    }

    /**
     * Gets iOS-specific bottom inset (home indicator area).
     */
    private int getIOSBottomInset() {
        // Home indicator area for devices without home button
        return 34;
    }

    /**
     * Gets iOS-specific right inset (for landscape orientation with notch).
     */
    private int getIOSRightInset() {
        return 0; // Usually 0, but could be adjusted for landscape notch
    }

    /**
     * Gets Android-specific top inset (status bar).
     */
    private int getAndroidTopInset() {
        // Standard Android status bar height
        return 24;
    }

    /**
     * Gets Android-specific left inset.
     */
    private int getAndroidLeftInset() {
        return 0; // Usually 0 unless there are navigation gestures
    }

    /**
     * Gets Android-specific bottom inset (navigation bar).
     */
    private int getAndroidBottomInset() {
        // Navigation bar height, may vary based on device and settings
        return 48;
    }

    /**
     * Gets Android-specific right inset.
     */
    private int getAndroidRightInset() {
        return 0; // Usually 0 unless there are navigation gestures
    }

    @Override
    public void render(Renderer renderer) {
        Insets safeInsets = getSafeAreaInsets();

        // Only apply padding if there are actual insets to apply
        if (safeInsets.top > 0 || safeInsets.left > 0 || 
            safeInsets.bottom > 0 || safeInsets.right > 0) {
            renderer.pushPadding(safeInsets);
            child.render(renderer);
            renderer.pop();
        } else {
            // No safe area needed, render child directly
            child.render(renderer);
        }
    }

    /**
     * Gets the child view.
     */
    public View getChild() {
        return child;
    }

    /**
     * Checks if top safe area is enabled.
     */
    public boolean isTopEnabled() {
        return top;
    }

    /**
     * Checks if left safe area is enabled.
     */
    public boolean isLeftEnabled() {
        return left;
    }

    /**
     * Checks if bottom safe area is enabled.
     */
    public boolean isBottomEnabled() {
        return bottom;
    }

    /**
     * Checks if right safe area is enabled.
     */
    public boolean isRightEnabled() {
        return right;
    }
}

package io.github._3xhaust.dsl;

import io.github._3xhaust.core.Renderer;
import io.github._3xhaust.core.View;
import io.github._3xhaust.platform.swing.SwingRenderer;
import io.github._3xhaust.theme.Colors;

import javax.swing.*;
import javax.swing.border.Border;
import java.awt.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class UnifiedWidget extends AbstractWidget {
    private final WidgetType type;
    private final String text;
    private final Runnable onClick;
    private final List<Widget> children;
    private final View child;
    private final Color backgroundColor;
    private final String imagePath;
    private final double width;
    private final double height;
    private final Color textColor;
    private final double gap;
    private final EdgeInsets padding;
    private final EdgeInsets margin;
    private final double borderRadius;
    private final Color borderColor;
    private final double borderWidth;
    private final int fontSize;
    private final boolean bold;
    private final boolean italic;
    private final String fontFamily;
    private final double opacity;
    private final boolean visible;
    private final int elevation;

    public enum WidgetType {
        TEXT, BUTTON, SCAFFOLD, CENTER, ROW, COLUMN, APPBAR, IMAGE,
        LISTVIEW, SCROLLVIEW, CONTAINER, EXPANDED, FLEXIBLE, SIZED_BOX, GRIDVIEW
    }

    private UnifiedWidget(Builder builder) {
        this.type = builder.type;
        this.text = builder.text;
        this.onClick = builder.onClick;
        this.children = builder.children != null ? new ArrayList<>(builder.children) : new ArrayList<>();
        this.child = builder.child;
        this.backgroundColor = builder.backgroundColor;
        this.imagePath = builder.imagePath;
        this.width = builder.width;
        this.height = builder.height;
        this.textColor = builder.textColor;
        this.gap = builder.gap;
        this.padding = builder.padding;
        this.margin = builder.margin;
        this.borderRadius = builder.borderRadius;
        this.borderColor = builder.borderColor;
        this.borderWidth = builder.borderWidth;
        this.fontSize = builder.fontSize;
        this.bold = builder.bold;
        this.italic = builder.italic;
        this.fontFamily = builder.fontFamily;
        this.opacity = builder.opacity;
        this.visible = builder.visible;
        this.elevation = builder.elevation;
    }

    public static class Builder {
        private WidgetType type;
        private String text;
        private Runnable onClick;
        private List<Widget> children;
        private View child;
        private Color backgroundColor;
        private String imagePath;
        private double width = -1;
        private double height = -1;
        private Color textColor;
        private double gap;
        private EdgeInsets padding;
        private EdgeInsets margin;
        private double borderRadius;
        private Color borderColor;
        private double borderWidth;
        private int fontSize = -1;
        private boolean bold;
        private boolean italic;
        private String fontFamily;
        private double opacity = 1.0;
        private boolean visible = true;
        private int elevation;

        public Builder type(WidgetType type) {
            this.type = type;
            return this;
        }

        public Builder text(String text) {
            this.text = text;
            return this;
        }

        public Builder onClick(Runnable onClick) {
            this.onClick = onClick;
            return this;
        }

        public Builder children(Widget... children) {
            this.children = Arrays.asList(children);
            return this;
        }

        public Builder children(List<Widget> children) {
            this.children = children;
            return this;
        }

        public Builder child(View child) {
            this.child = child;
            return this;
        }

        public Builder backgroundColor(Color backgroundColor) {
            this.backgroundColor = backgroundColor;
            return this;
        }

        public Builder imagePath(String imagePath) {
            this.imagePath = imagePath;
            return this;
        }

        public Builder width(double width) {
            this.width = width;
            return this;
        }

        public Builder height(double height) {
            this.height = height;
            return this;
        }

        public Builder textColor(Color textColor) {
            this.textColor = textColor;
            return this;
        }

        public Builder gap(double gap) {
            this.gap = gap;
            return this;
        }

        public Builder padding(EdgeInsets padding) {
            this.padding = padding;
            return this;
        }

        public Builder margin(EdgeInsets margin) {
            this.margin = margin;
            return this;
        }

        public Builder borderRadius(double borderRadius) {
            this.borderRadius = borderRadius;
            return this;
        }

        public Builder borderColor(Color borderColor) {
            this.borderColor = borderColor;
            return this;
        }

        public Builder borderWidth(double borderWidth) {
            this.borderWidth = borderWidth;
            return this;
        }

        public Builder fontSize(int fontSize) {
            this.fontSize = fontSize;
            return this;
        }

        public Builder bold(boolean bold) {
            this.bold = bold;
            return this;
        }

        public Builder italic(boolean italic) {
            this.italic = italic;
            return this;
        }

        public Builder fontFamily(String fontFamily) {
            this.fontFamily = fontFamily;
            return this;
        }

        public Builder opacity(double opacity) {
            this.opacity = opacity;
            return this;
        }

        public Builder visible(boolean visible) {
            this.visible = visible;
            return this;
        }

        public Builder elevation(int elevation) {
            this.elevation = elevation;
            return this;
        }

        public UnifiedWidget build() {
            return new UnifiedWidget(this);
        }
    }

    public static Builder builder() {
        return new Builder();
    }

    @Override
    public List<Widget> getChildren() {
        return children;
    }

    public UnifiedWidget width(double width) {
        return copyWith().width(width).build();
    }

    public UnifiedWidget height(double height) {
        return copyWith().height(height).build();
    }

    public UnifiedWidget color(Color color) {
        return copyWith().textColor(color).build();
    }

    public UnifiedWidget backgroundColor(Color color) {
        return copyWith().backgroundColor(color).build();
    }

    public UnifiedWidget gap(double gap) {
        return copyWith().gap(gap).build();
    }

    public UnifiedWidget padding(EdgeInsets padding) {
        return copyWith().padding(padding).build();
    }

    public UnifiedWidget padding(double all) {
        return copyWith().padding(EdgeInsets.all(all)).build();
    }

    public UnifiedWidget margin(EdgeInsets margin) {
        return copyWith().margin(margin).build();
    }

    public UnifiedWidget margin(double all) {
        return copyWith().margin(EdgeInsets.all(all)).build();
    }

    public UnifiedWidget borderRadius(double radius) {
        return copyWith().borderRadius(radius).build();
    }

    public UnifiedWidget border(Color color, double width) {
        return copyWith().borderColor(color).borderWidth(width).build();
    }

    public UnifiedWidget fontSize(int size) {
        return copyWith().fontSize(size).build();
    }

    public UnifiedWidget fontWeight(int weight) {
        return copyWith().bold(weight == Font.BOLD).italic(weight == Font.ITALIC).build();
    }

    public UnifiedWidget fontFamily(String family) {
        return copyWith().fontFamily(family).build();
    }

    public UnifiedWidget opacity(double opacity) {
        return copyWith().opacity(opacity).build();
    }

/* <<<<<<<<<<<<<<  ✨ Windsurf Command ⭐ >>>>>>>>>>>>>>>> */
    /**
     * Creates a copy of the widget with the given visibility.
     *
     * @param visible true if the widget should be visible, false otherwise
     * @return a new widget with the given visibility
     */
/* <<<<<<<<<<  72edc852-78c8-4fcc-9376-c6879780aade  >>>>>>>>>>> */
    public UnifiedWidget visible(boolean visible) {
        return copyWith().visible(visible).build();
    }

    public UnifiedWidget elevation(int elevation) {
        return copyWith().elevation(elevation).build();
    }

    private Builder copyWith() {
        return builder()
                .type(this.type)
                .text(this.text)
                .onClick(this.onClick)
                .children(this.children)
                .child(this.child)
                .backgroundColor(this.backgroundColor)
                .imagePath(this.imagePath)
                .width(this.width)
                .height(this.height)
                .textColor(this.textColor)
                .gap(this.gap)
                .padding(this.padding)
                .margin(this.margin)
                .borderRadius(this.borderRadius)
                .borderColor(this.borderColor)
                .borderWidth(this.borderWidth)
                .fontSize(this.fontSize)
                .bold(this.bold)
                .italic(this.italic)
                .fontFamily(this.fontFamily)
                .opacity(this.opacity)
                .visible(this.visible)
                .elevation(this.elevation);
    }

    @Override
    public void render(Renderer renderer) {
        if (!visible) return;

        if (renderer instanceof SwingRenderer swing) {
            switch (type) {
                case TEXT -> {
                    JLabel label = new JLabel(text);
                    applyStyles(label);
                    swing.addComponent(label);
                }
                case BUTTON -> {
                    JButton button = new JButton(text);
                    button.setBackground(backgroundColor != null ? backgroundColor : Colors.Blue500);
                    button.setForeground(textColor != null ? textColor : Color.BLACK);
                    applyStyles(button);
                    if (onClick != null) {
                        button.addActionListener(e -> onClick.run());
                    }
                    swing.addComponent(button);
                }
                case CENTER -> {
                    JPanel panel = new JPanel(new GridBagLayout());
                    applyStyles(panel);
                    swing.pushContainer(panel);
                    if (child != null) {
                        child.render(swing);
                    }
                    swing.popContainer();
                    swing.addComponent(panel);
                }
                case ROW -> {
                    JPanel panel = new JPanel(new FlowLayout(FlowLayout.LEFT, (int) gap, 0));
                    applyStyles(panel);
                    swing.pushContainer(panel);
                    for (Widget child : children) {
                        child.render(swing);
                    }
                    swing.popContainer();
                    swing.addComponent(panel);
                }
                case COLUMN -> {
                    JPanel panel = new JPanel();
                    panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
                    applyStyles(panel);
                    swing.pushContainer(panel);
                    for (int i = 0; i < children.size(); i++) {
                        children.get(i).render(swing);
                        if (i < children.size() - 1 && gap > 0) {
                            panel.add(Box.createVerticalStrut((int) gap));
                        }
                    }
                    swing.popContainer();
                    swing.addComponent(panel);
                }
                case APPBAR -> {
                    JPanel appBar = new JPanel(new BorderLayout());
                    appBar.setBackground(backgroundColor != null ? backgroundColor : Colors.Teal500);
                    applyStyles(appBar);
                    swing.pushContainer(appBar);
                    if (child != null) {
                        child.render(swing);
                    }
                    swing.popContainer();
                    swing.addComponent(appBar);
                }
                case IMAGE -> {
                    if (imagePath != null) {
                        ImageIcon icon = new ImageIcon(imagePath);
                        if (width > 0 || height > 0) {
                            Image img = icon.getImage();
                            int newWidth = width > 0 ? (int) width : icon.getIconWidth();
                            int newHeight = height > 0 ? (int) height : icon.getIconHeight();
                            Image scaledImg = img.getScaledInstance(newWidth, newHeight, Image.SCALE_SMOOTH);
                            icon = new ImageIcon(scaledImg);
                        }
                        JLabel imageLabel = new JLabel(icon);
                        applyStyles(imageLabel);
                        swing.addComponent(imageLabel);
                    }
                }
                case SCAFFOLD -> {
                    JPanel scaffold = new JPanel(new BorderLayout());
                    applyStyles(scaffold);
                    swing.addComponent(scaffold);
                }
            }
        }
    }

    private void applyStyles(JComponent component) {
        if (backgroundColor != null) {
            component.setBackground(backgroundColor);
            component.setOpaque(true);
        }

        if (width > 0 || height > 0) {
            Dimension size = new Dimension(
                width > 0 ? (int) width : component.getPreferredSize().width,
                height > 0 ? (int) height : component.getPreferredSize().height
            );
            component.setPreferredSize(size);
        }

        if (component instanceof JLabel label && textColor != null) {
            label.setForeground(textColor);
        }

        if (fontSize > 0 || bold || italic || fontFamily != null) {
            Font currentFont = component.getFont();
            String family = fontFamily != null ? fontFamily : currentFont.getFontName();
            int size = fontSize > 0 ? fontSize : currentFont.getSize();
            int style = Font.PLAIN;
            if (bold) style |= Font.BOLD;
            if (italic) style |= Font.ITALIC;
            component.setFont(new Font(family, style, size));
        }

        if (opacity < 1.0 && component.getBackground() != null) {
            component.setBackground(new Color(
                component.getBackground().getRed(),
                component.getBackground().getGreen(),
                component.getBackground().getBlue(),
                (int) (255 * opacity)
            ));
        }

        if (padding != null) {
            component.setBorder(BorderFactory.createEmptyBorder(
                (int) padding.top,
                (int) padding.left,
                (int) padding.bottom,
                (int) padding.right
            ));
        }

        if (borderWidth > 0 && borderColor != null) {
            if (borderRadius > 0) {
                component.setBorder(BorderFactory.createCompoundBorder(
                    new RoundBorder(borderColor, (int) borderWidth, (int) borderRadius),
                    component.getBorder()
                ));
            } else {
                component.setBorder(BorderFactory.createCompoundBorder(
                    BorderFactory.createLineBorder(borderColor, (int) borderWidth),
                    component.getBorder()
                ));
            }
        }

        if (elevation > 0) {
            component.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createRaisedBevelBorder(),
                component.getBorder()
            ));
        }
    }

    private static class RoundBorder implements Border {
        private final Color color;
        private final int thickness;
        private final int radius;

        public RoundBorder(Color color, int thickness, int radius) {
            this.color = color;
            this.thickness = thickness;
            this.radius = radius;
        }

        @Override
        public void paintBorder(Component c, Graphics g, int x, int y, int width, int height) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setColor(color);
            g2.setStroke(new BasicStroke(thickness));
            g2.drawRoundRect(x, y, width - 1, height - 1, radius, radius);
            g2.dispose();
        }

        @Override
        public Insets getBorderInsets(Component c) {
            return new Insets(thickness, thickness, thickness, thickness);
        }

        @Override
        public boolean isBorderOpaque() {
            return false;
        }
    }
}

package io.github._3xhaust.dsl;

import io.github._3xhaust.core.Renderer;
import io.github._3xhaust.core.View;
import io.github._3xhaust.platform.swing.SwingRenderer;
import io.github._3xhaust.theme.Colors;

import javax.swing.*;
import javax.swing.border.Border;
import java.awt.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class UnifiedWidget extends AbstractWidget {
    private final WidgetType type;
    private final String text;
    private final Runnable onClick;
    private final List<Widget> children;
    private final View child;
    private final Color backgroundColor;
    private final String imagePath;
    private final double width;
    private final double height;
    private final Color textColor;
    private final double gap;
    private final EdgeInsets padding;
    private final EdgeInsets margin;
    private final double borderRadius;
    private final Color borderColor;
    private final double borderWidth;
    private final int fontSize;
    private final boolean bold;
    private final boolean italic;
    private final String fontFamily;
    private final double opacity;
    private final boolean visible;
    private final int elevation;

    public enum WidgetType {
        TEXT, BUTTON, SCAFFOLD, CENTER, ROW, COLUMN, APPBAR, IMAGE,
        LISTVIEW, SCROLLVIEW, CONTAINER, EXPANDED, FLEXIBLE, SIZED_BOX, GRIDVIEW
    }

    private UnifiedWidget(Builder builder) {
        this.type = builder.type;
        this.text = builder.text;
        this.onClick = builder.onClick;
        this.children = builder.children != null ? new ArrayList<>(builder.children) : new ArrayList<>();
        this.child = builder.child;
        this.backgroundColor = builder.backgroundColor;
        this.imagePath = builder.imagePath;
        this.width = builder.width;
        this.height = builder.height;
        this.textColor = builder.textColor;
        this.gap = builder.gap;
        this.padding = builder.padding;
        this.margin = builder.margin;
        this.borderRadius = builder.borderRadius;
        this.borderColor = builder.borderColor;
        this.borderWidth = builder.borderWidth;
        this.fontSize = builder.fontSize;
        this.bold = builder.bold;
        this.italic = builder.italic;
        this.fontFamily = builder.fontFamily;
        this.opacity = builder.opacity;
        this.visible = builder.visible;
        this.elevation = builder.elevation;
    }

    public static class Builder {
        private WidgetType type;
        private String text;
        private Runnable onClick;
        private List<Widget> children;
        private View child;
        private Color backgroundColor;
        private String imagePath;
        private double width = -1;
        private double height = -1;
        private Color textColor;
        private double gap;
        private EdgeInsets padding;
        private EdgeInsets margin;
        private double borderRadius;
        private Color borderColor;
        private double borderWidth;
        private int fontSize = -1;
        private boolean bold;
        private boolean italic;
        private String fontFamily;
        private double opacity = 1.0;
        private boolean visible = true;
        private int elevation;

        public Builder type(WidgetType type) {
            this.type = type;
            return this;
        }

        public Builder text(String text) {
            this.text = text;
            return this;
        }

        public Builder onClick(Runnable onClick) {
            this.onClick = onClick;
            return this;
        }

        public Builder children(Widget... children) {
            this.children = Arrays.asList(children);
            return this;
        }

        public Builder children(List<Widget> children) {
            this.children = children;
            return this;
        }

        public Builder child(View child) {
            this.child = child;
            return this;
        }

        public Builder backgroundColor(Color backgroundColor) {
            this.backgroundColor = backgroundColor;
            return this;
