        public Builder width(double width) {
            this.width = width;
            return this;
        }

        public Builder height(double height) {
            this.height = height;
            return this;
        }

        public Builder textColor(Color textColor) {
            this.textColor = textColor;
            return this;
        }

        public Builder gap(double gap) {
            this.gap = gap;
            return this;
        }

        public Builder padding(EdgeInsets padding) {
            this.padding = padding;
            return this;
        }

        public Builder margin(EdgeInsets margin) {
            this.margin = margin;
            return this;
        }

        public Builder borderRadius(double borderRadius) {
            this.borderRadius = borderRadius;
            return this;
        }

        public Builder borderColor(Color borderColor) {
            this.borderColor = borderColor;
            return this;
        }

        public Builder borderWidth(double borderWidth) {
            this.borderWidth = borderWidth;
            return this;
