        public UnifiedWidget build() {
            return new UnifiedWidget(this);
        }
    }

    public static Builder builder() {
        return new Builder();
    }

    @Override
    public List<Widget> getChildren() {
        return children;
    }

    public UnifiedWidget width(double width) {
        return copyWith().width(width).build();
    }

    public UnifiedWidget height(double height) {
        return copyWith().height(height).build();
    }

    public UnifiedWidget color(Color color) {
        return copyWith().textColor(color).build();
    }

    public UnifiedWidget backgroundColor(Color color) {
        return copyWith().backgroundColor(color).build();
    }

    public UnifiedWidget gap(double gap) {
        return copyWith().gap(gap).build();
    }

    public UnifiedWidget padding(EdgeInsets padding) {
        return copyWith().padding(padding).build();
    }

    public UnifiedWidget padding(double all) {
        return copyWith().padding(EdgeInsets.all(all)).build();
    }

    public UnifiedWidget margin(EdgeInsets margin) {
        return copyWith().margin(margin).build();
    }

    public UnifiedWidget margin(double all) {
        return copyWith().margin(EdgeInsets.all(all)).build();
    }

    public UnifiedWidget borderRadius(double radius) {
        return copyWith().borderRadius(radius).build();
    }

    public UnifiedWidget border(Color color, double width) {
        return copyWith().borderColor(color).borderWidth(width).build();
    }

    public UnifiedWidget fontSize(int size) {
        return copyWith().fontSize(size).build();
    }

    public UnifiedWidget fontWeight(int weight) {
        return copyWith().bold(weight == Font.BOLD).italic(weight == Font.ITALIC).build();
    }

    public UnifiedWidget fontFamily(String family) {
        return copyWith().fontFamily(family).build();
    }

    public UnifiedWidget opacity(double opacity) {
        return copyWith().opacity(opacity).build();
    }

/* <<<<<<<<<<<<<<  ✨ Windsurf Command ⭐ >>>>>>>>>>>>>>>> */
    /**
     * Creates a copy of the widget with the given visibility.
     *
     * @param visible true if the widget should be visible, false otherwise
     * @return a new widget with the given visibility
     */
/* <<<<<<<<<<  72edc852-78c8-4fcc-9376-c6879780aade  >>>>>>>>>>> */
    public UnifiedWidget visible(boolean visible) {
        return copyWith().visible(visible).build();
    }

    public UnifiedWidget elevation(int elevation) {
        return copyWith().elevation(elevation).build();
    }

    private Builder copyWith() {
        return builder()
                .type(this.type)
                .text(this.text)
                .onClick(this.onClick)
                .children(this.children)
                .child(this.child)
                .backgroundColor(this.backgroundColor)
                .imagePath(this.imagePath)
                .width(this.width)
                .height(this.height)
                .textColor(this.textColor)
                .gap(this.gap)
                .padding(this.padding)
                .margin(this.margin)
                .borderRadius(this.borderRadius)
                .borderColor(this.borderColor)
                .borderWidth(this.borderWidth)
                .fontSize(this.fontSize)
                .bold(this.bold)
                .italic(this.italic)
                .fontFamily(this.fontFamily)
                .opacity(this.opacity)
                .visible(this.visible)
                .elevation(this.elevation);
    }

    @Override
    public void render(Renderer renderer) {
        if (!visible) return;

        if (renderer instanceof SwingRenderer swing) {
            switch (type) {
                case TEXT -> {
                    JLabel label = new JLabel(text);
                    applyStyles(label);
                    swing.addComponent(label);
                }
                case BUTTON -> {
                    JButton button = new JButton(text);
                    button.setBackground(backgroundColor != null ? backgroundColor : Colors.Blue500);
                    button.setForeground(textColor != null ? textColor : Color.BLACK);
                    applyStyles(button);
                    if (onClick != null) {
                        button.addActionListener(e -> onClick.run());
                    }
                    swing.addComponent(button);
                }
                case CENTER -> {
                    JPanel panel = new JPanel(new GridBagLayout());
                    applyStyles(panel);
                    swing.pushContainer(panel);
                    if (child != null) {
                        child.render(swing);
                    }
                    swing.popContainer();
                    swing.addComponent(panel);
                }
                case ROW -> {
                    JPanel panel = new JPanel(new FlowLayout(FlowLayout.LEFT, (int) gap, 0));
                    applyStyles(panel);
                    swing.pushContainer(panel);
                    for (Widget child : children) {
                        child.render(swing);
                    }
                    swing.popContainer();
                    swing.addComponent(panel);
                }
                case COLUMN -> {
                    JPanel panel = new JPanel();
                    panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
                    applyStyles(panel);
                    swing.pushContainer(panel);
                    for (int i = 0; i < children.size(); i++) {
                        children.get(i).render(swing);
                        if (i < children.size() - 1 && gap > 0) {
                            panel.add(Box.createVerticalStrut((int) gap));
                        }
                    }
                    swing.popContainer();
                    swing.addComponent(panel);
                }
                case APPBAR -> {
                    JPanel appBar = new JPanel(new BorderLayout());
                    appBar.setBackground(backgroundColor != null ? backgroundColor : Colors.Teal500);
                    applyStyles(appBar);
                    swing.pushContainer(appBar);
                    if (child != null) {
                        child.render(swing);
                    }
                    swing.popContainer();
                    swing.addComponent(appBar);
                }
                case IMAGE -> {
                    if (imagePath != null) {
                        try {
                            ImageIcon icon = new ImageIcon(imagePath);

                            // 이미지가 로드되지 않았거나 크기가 0인 경우 처리
                            if (icon.getIconWidth() <= 0 || icon.getIconHeight() <= 0) {
                                // 클래스패스에서 리소스로 시도
                                java.net.URL imageUrl = getClass().getClassLoader().getResource(imagePath);
                                if (imageUrl != null) {
                                    icon = new ImageIcon(imageUrl);
                                } else {
                                    // 이미지 로드 실패시 기본 텍스트 표시
                                    JLabel errorLabel = new JLabel("Image not found: " + imagePath);
                                    errorLabel.setBorder(BorderFactory.createLineBorder(Color.RED));
                                    applyStyles(errorLabel);
                                    swing.addComponent(errorLabel);
                                    return;
                                }
                            }

                            if (width > 0 || height > 0) {
                                Image img = icon.getImage();
                                int newWidth = width > 0 ? (int) width : icon.getIconWidth();
                                int newHeight = height > 0 ? (int) height : icon.getIconHeight();
                                Image scaledImg = img.getScaledInstance(newWidth, newHeight, Image.SCALE_SMOOTH);
                                icon = new ImageIcon(scaledImg);
                            }

                            JLabel imageLabel = new JLabel(icon);
                            applyStyles(imageLabel);
                            swing.addComponent(imageLabel);
                        } catch (Exception e) {
                            // 예외 발생시 오류 메시지 표시
                            JLabel errorLabel = new JLabel("Error loading image: " + imagePath);
                            errorLabel.setBorder(BorderFactory.createLineBorder(Color.RED));
                            applyStyles(errorLabel);
                            swing.addComponent(errorLabel);
                        }
                    } else {
                        // imagePath가 null인 경우
                        JLabel errorLabel = new JLabel("No image path specified");
                        errorLabel.setBorder(BorderFactory.createLineBorder(Color.GRAY));
                        applyStyles(errorLabel);
                        swing.addComponent(errorLabel);
                    }
                }
                case SCAFFOLD -> {
                    JPanel scaffold = new JPanel(new BorderLayout());
                    applyStyles(scaffold);
                    swing.addComponent(scaffold);
                }
            }
        }
    }

    private void applyStyles(JComponent component) {
        if (backgroundColor != null) {
            component.setBackground(backgroundColor);
            component.setOpaque(true);
        }

        if (width > 0 || height > 0) {
            Dimension size = new Dimension(
                width > 0 ? (int) width : component.getPreferredSize().width,
                height > 0 ? (int) height : component.getPreferredSize().height
            );
            component.setPreferredSize(size);
        }

        if (component instanceof JLabel label && textColor != null) {
            label.setForeground(textColor);
        }

        if (fontSize > 0 || bold || italic || fontFamily != null) {
            Font currentFont = component.getFont();
            String family = fontFamily != null ? fontFamily : currentFont.getFontName();
            int size = fontSize > 0 ? fontSize : currentFont.getSize();
            int style = Font.PLAIN;
            if (bold) style |= Font.BOLD;
            if (italic) style |= Font.ITALIC;
            component.setFont(new Font(family, style, size));
        }

        if (opacity < 1.0 && component.getBackground() != null) {
            component.setBackground(new Color(
                component.getBackground().getRed(),
                component.getBackground().getGreen(),
                component.getBackground().getBlue(),
                (int) (255 * opacity)
            ));
        }

        if (padding != null) {
            component.setBorder(BorderFactory.createEmptyBorder(
                (int) padding.top,
                (int) padding.left,
                (int) padding.bottom,
                (int) padding.right
            ));
        }

        if (borderWidth > 0 && borderColor != null) {
            if (borderRadius > 0) {
                component.setBorder(BorderFactory.createCompoundBorder(
                    new RoundBorder(borderColor, (int) borderWidth, (int) borderRadius),
                    component.getBorder()
                ));
            } else {
                component.setBorder(BorderFactory.createCompoundBorder(
                    BorderFactory.createLineBorder(borderColor, (int) borderWidth),
                    component.getBorder()
                ));
            }
        }

        if (elevation > 0) {
            component.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createRaisedBevelBorder(),
                component.getBorder()
            ));
        }
    }

    private static class RoundBorder implements Border {
        private final Color color;
        private final int thickness;
        private final int radius;

        public RoundBorder(Color color, int thickness, int radius) {
            this.color = color;
            this.thickness = thickness;
            this.radius = radius;
        }

        @Override
        public void paintBorder(Component c, Graphics g, int x, int y, int width, int height) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setColor(color);
            g2.setStroke(new BasicStroke(thickness));
            g2.drawRoundRect(x, y, width - 1, height - 1, radius, radius);
            g2.dispose();
        }

        @Override
        public Insets getBorderInsets(Component c) {
            return new Insets(thickness, thickness, thickness, thickness);
        }

        @Override
        public boolean isBorderOpaque() {
            return false;
        }
    }
}

package io.github._3xhaust.dsl;

import io.github._3xhaust.core.View;

import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.util.HashMap;
import java.util.Map;

public class W {
    private static final Map<String, Method> factoryMethods = new HashMap<>();
    private static boolean initialized = false;

    static {
        initialize();
    }

    private static void initialize() {
        if (initialized) return;

        registerBuiltinFactories();
        scanForCustomFactories();

        initialized = true;
    }

    private static void registerBuiltinFactories() {
        try {
            factoryMethods.put("Text", W.class.getMethod("Text", String.class));
            factoryMethods.put("Button", W.class.getMethod("Button", String.class, Runnable.class));
            factoryMethods.put("Image", W.class.getMethod("Image", String.class));
            factoryMethods.put("Row", W.class.getMethod("Row", Widget[].class));
            factoryMethods.put("Column", W.class.getMethod("Column", Widget[].class));
            factoryMethods.put("Center", W.class.getMethod("Center", View.class));
            factoryMethods.put("Container", W.class.getMethod("Container"));
        } catch (NoSuchMethodException e) {
            throw new RuntimeException("Failed to register builtin factories", e);
        }
    }

    private static void scanForCustomFactories() {
        Class<?>[] classes = {
            io.github._3xhaust.dsl.widgets.ScaffoldWidget.class
        };

        for (Class<?> clazz : classes) {
            String className = clazz.getSimpleName().replace("Widget", "");
            try {
                Method constructor = clazz.getConstructor();
                factoryMethods.put(className, constructor);
            } catch (NoSuchMethodException e) {
            }
        }
    }

    public static UnifiedWidget Text(String text) {
        return UnifiedWidget.builder()
                .type(UnifiedWidget.WidgetType.TEXT)
                .text(text)
                .build();
    }

    public static UnifiedWidget Button(String text, Runnable onClick) {
        return UnifiedWidget.builder()
                .type(UnifiedWidget.WidgetType.BUTTON)
                .text(text)
                .onClick(onClick)
                .build();
    }

    public static UnifiedWidget Button(String text) {
        return Button(text, null);
    }

    public static UnifiedWidget Image(String path) {
        return UnifiedWidget.builder()
                .type(UnifiedWidget.WidgetType.IMAGE)
                .imagePath(path)
                .build();
    }

    public static UnifiedWidget Row(Widget... children) {
        return UnifiedWidget.builder()
                .type(UnifiedWidget.WidgetType.ROW)
                .children(children)
                .build();
    }

    public static UnifiedWidget Column(Widget... children) {
        return UnifiedWidget.builder()
                .type(UnifiedWidget.WidgetType.COLUMN)
                .children(children)
                .build();
    }

    public static UnifiedWidget Center(View child) {
        return UnifiedWidget.builder()
                .type(UnifiedWidget.WidgetType.CENTER)
                .child(child)
                .build();
    }

    public static UnifiedWidget Container() {
        return UnifiedWidget.builder()
                .type(UnifiedWidget.WidgetType.CONTAINER)
                .build();
    }

    public static UnifiedWidget ListView(Widget... children) {
        return UnifiedWidget.builder()
                .type(UnifiedWidget.WidgetType.LISTVIEW)
                .children(children)
                .build();
    }

    public static UnifiedWidget ScrollView(View child) {
        return UnifiedWidget.builder()
                .type(UnifiedWidget.WidgetType.SCROLLVIEW)
                .child(child)
                .build();
    }

    public static UnifiedWidget AppBar(View title) {
        return UnifiedWidget.builder()
                .type(UnifiedWidget.WidgetType.APPBAR)
                .child(title)
                .build();
    }

    public static UnifiedWidget GridView(Widget... children) {
        return UnifiedWidget.builder()
                .type(UnifiedWidget.WidgetType.GRIDVIEW)
                .children(children)
                .build();
    }

    public static UnifiedWidget SizedBox(double width, double height) {
        return UnifiedWidget.builder()
                .type(UnifiedWidget.WidgetType.SIZED_BOX)
                .width(width)
                .height(height)
                .build();
    }

    public static UnifiedWidget Expanded(Widget child) {
        return UnifiedWidget.builder()
                .type(UnifiedWidget.WidgetType.EXPANDED)
                .child(child)
                .build();
    }

    public static UnifiedWidget Flexible(Widget child) {
        return UnifiedWidget.builder()
                .type(UnifiedWidget.WidgetType.FLEXIBLE)
                .child(child)
                .build();
    }

    public static Object create(String widgetName, Object... args) {
        try {
            Method method = factoryMethods.get(widgetName);
            if (method != null) {
                if (Modifier.isStatic(method.getModifiers()) && method.getDeclaringClass() == W.class) {
                    return method.invoke(null, args);
                } else {
                    return method.getDeclaringClass().getDeclaredConstructor().newInstance();
                }
            }

            String className = "io.github._3xhaust.dsl.widgets." + widgetName + "Widget";
            Class<?> clazz = Class.forName(className);
            return clazz.getDeclaredConstructor().newInstance();

        } catch (Exception e) {
            throw new RuntimeException("Failed to create widget: " + widgetName, e);
        }
    }

    public static void registerCustomWidget(Class<?> widgetClass) {
        String name = widgetClass.getSimpleName().replace("Widget", "");
        try {
            Method constructor = widgetClass.getConstructor();
            factoryMethods.put(name, constructor);
        } catch (NoSuchMethodException e) {
            System.err.println("Widget " + widgetClass.getSimpleName() + " must have a no-args constructor");
        }
    }
}

package io.github._3xhaust.dsl;

import io.github._3xhaust.core.View;

/**
 * 위젯 팩토리 인터페이스
 * 각 위젯은 이 인터페이스를 구현하여 자동으로 등록될 수 있습니다.
 */
public interface WidgetFactory {
    /**
     * 위젯의 이름을 반환합니다.
     * @return 위젯 이름 (예: "Text", "Button")
     */
    String getWidgetName();

    /**
     * 위젯이 지원하는 파라미터 타입들을 반환합니다.
     * @return 파라미터 타입 배열
     */
    Class<?>[] getSupportedParameterTypes();

    /**
     * 주어진 파라미터로 위젯을 생성합니다.
     * @param parameters 위젯 생성에 필요한 파라미터들
     * @return 생성된 View 인스턴스
     */
    View createWidget(Object... parameters);

    /**
     * 이 팩토리가 주어진 파라미터들로 위젯을 생성할 수 있는지 확인합니다.
     * @param parameters 확인할 파라미터들
     * @return 생성 가능 여부
     */
    boolean canCreate(Object... parameters);
}
